/// Renders an MMIcon scaled from its 24×24 viewBox, stroke-weighted to match
/// the 2pt-at-24px source.
struct IconView: View {
    let icon: MMIcon
    var size: CGFloat = 16
    var color: Color = MM.Colors.textSecondary

    var body: some View {
        SVGShape(svgPath: icon.svgPath)
            .stroke(color, style: StrokeStyle(
                lineWidth: size / 12, lineCap: .round, lineJoin: .round))
            .frame(width: size, height: size)
    }
}

/// Parses a minimal SVG path (M, L, C, V, H, Z + lowercase relatives) and
/// scales from the 24×24 viewBox into the SwiftUI frame.
struct SVGShape: Shape {
    let svgPath: String

    func path(in rect: CGRect) -> Path {
        let sx = rect.width / 24
        let sy = rect.height / 24
        var path = Path()
        let tokens = tokenize(svgPath)
        var i = 0
        var cx = 0.0, cy = 0.0
        var startX = 0.0, startY = 0.0

        func num() -> Double {
            guard i < tokens.count, let v = Double(tokens[i]) else { return 0 }
            i += 1
            return v
        }
        func pt(_ x: Double, _ y: Double) -> CGPoint { CGPoint(x: x * sx, y: y * sy) }

        while i < tokens.count {
            let cmd = tokens[i]; i += 1
            switch cmd {
            case "M":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx = num(); cy = num()
                    path.move(to: pt(cx, cy))
                    startX = cx; startY = cy
                }
            case "m":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx += num(); cy += num()
                    path.move(to: pt(cx, cy))
                    startX = cx; startY = cy
                }
            case "L":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx = num(); cy = num()
                    path.addLine(to: pt(cx, cy))
                }
            case "l":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx += num(); cy += num()
                    path.addLine(to: pt(cx, cy))
                }
            case "H":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx = num(); path.addLine(to: pt(cx, cy))
                }
            case "h":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cx += num(); path.addLine(to: pt(cx, cy))
                }
            case "V":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cy = num(); path.addLine(to: pt(cx, cy))
                }
            case "v":
                while i < tokens.count, Double(tokens[i]) != nil {
                    cy += num(); path.addLine(to: pt(cx, cy))
                }
            case "C":
                while i < tokens.count, Double(tokens[i]) != nil {
                    let x1 = num(), y1 = num(), x2 = num(), y2 = num()
                    cx = num(); cy = num()
                    path.addCurve(to: pt(cx, cy), control1: pt(x1, y1), control2: pt(x2, y2))
                }
            case "c":
                while i < tokens.count, Double(tokens[i]) != nil {
                    let x1 = cx + num(), y1 = cy + num(), x2 = cx + num(), y2 = cy + num()
                    cx += num(); cy += num()
                    path.addCurve(to: pt(cx, cy), control1: pt(x1, y1), control2: pt(x2, y2))
                }
            case "Z", "z":
                path.closeSubpath()
                cx = startX; cy = startY
            default: break
            }
        }
        return path
    }

    private func tokenize(_ d: String) -> [String] {
        var result: [String] = []
        var current = ""
        for ch in d {
            if ch.isLetter {
                if !current.isEmpty { result.append(current); current = "" }
                result.append(String(ch))
            } else if ch == "," || ch == " " || ch == "\n" {
                if !current.isEmpty { result.append(current); current = "" }
            } else if ch == "-" && !current.isEmpty && !current.hasSuffix("e") {
                result.append(current); current = String(ch)
            } else {
                current.append(ch)
            }
        }
        if !current.isEmpty { result.append(current) }
        return result
    }
}
